  interface

    !---------------------------------------------
    ! rocsolver_log_begin
    !---------------------------------------------
    !>  \brief The LOG_BEGIN function initiates a rocSOLVER multi-level logging session.
    !>
    !>     \details
    !>     Initializes the rocSOLVER logging environment with default values (no
    !>     logging and one level depth). Default mode can be overridden by using the
    !>     environment variables ``ROCSOLVER_LAYER`` and ``ROCSOLVER_LEVELS``.
    !>
    !>     This function also sets the streams for the log results output.
    !>     The default is ``STDERR`` for all modes. This default can be overridden
    !>     using the environment variable ``ROCSOLVER_LOG_PATH``, or, more specifically,
    !>     ``ROCSOLVER_LOG_TRACE_PATH``, ``ROCSOLVER_LOG_BENCH_PATH``, and
    !>     ``ROCSOLVER_LOG_PROFILE_PATH``.
    function rocsolver_log_begin() &
       result(log_begin) &
       bind(C, name="rocsolver_log_begin")
       import :: rocblas_status_success
       integer(kind(rocblas_status_success)) :: log_begin
    end function rocsolver_log_begin

    !---------------------------------------------
    ! rocsolver_log_end
    !---------------------------------------------
    !>  \brief The LOG_END function ends the multi-level rocSOLVER logging session.
    !>
    !>     \details
    !>     If applicable, this function also prints the profile logging results
    !>     before cleaning the logging environment.
    function rocsolver_log_end() &
       result(log_end) &
       bind(C, name="rocsolver_log_end")
       import :: rocblas_status_success
       integer(kind(rocblas_status_success)) :: log_end
    end function rocsolver_log_end

    !---------------------------------------------
    ! rocsolver_log_set_layer_mode
    !---------------------------------------------
    !>  \brief The LOG_SET_LAYER_MODE function sets the logging mode for the rocSOLVER multi-level
    !>     logging environment.
    !>
    !>     \details
    !>     @param[in] layer_mode - rocblas_layer_mode_flags.
    !>                 Specifies the logging mode.
    function rocsolver_log_set_layer_mode(layer_mode) &
       result(log_set_layer_mode) &
       bind(C, name="rocsolver_log_set_layer_mode")
       import :: c_int, rocblas_status_success
       integer(c_int), value :: layer_mode
       integer(kind(rocblas_status_success)) :: log_set_layer_mode
    end function rocsolver_log_set_layer_mode

    !---------------------------------------------
    ! rocsolver_log_set_max_levels
    !---------------------------------------------
    !>  \brief The LOG_SET_MAX_LEVELS function sets the maximum trace log depth for the rocSOLVER
    !>     multi-level logging environment.
    !>
    !>     \details
    !>     @param[in] max_levels - rocblas_int. max_levels >= 1.
    !>                 Specifies the maximum depth for which nested function calls
    !>                 will appear in the trace and profile logs.
    function rocsolver_log_set_max_levels(max_levels) &
       result(log_set_max_levels) &
       bind(C, name="rocsolver_log_set_max_levels")
       import :: c_int, rocblas_status_success
       integer(c_int), value :: max_levels
       integer(kind(rocblas_status_success)) :: log_set_max_levels
    end function rocsolver_log_set_max_levels

    !---------------------------------------------
    ! rocsolver_log_restore_defaults
    !---------------------------------------------
    !>  \brief The LOG_RESTORE_DEFAULTS function restores the default values of the rocSOLVER
    !>     multi-level logging environment.
    !>
    !>     \details
    !>     This function sets the logging mode and maximum trace log depth to their
    !>     default values (no logging and one level depth).
    function rocsolver_log_restore_defaults() &
       result(log_restore_defaults) &
       bind(C, name="rocsolver_log_restore_defaults")
       import :: rocblas_status_success
       integer(kind(rocblas_status_success)) :: log_restore_defaults
    end function rocsolver_log_restore_defaults

    !---------------------------------------------
    ! rocsolver_log_write_profile
    !---------------------------------------------
    !>  \brief The LOG_WRITE_PROFILE function prints the profile logging results.
    function rocsolver_log_write_profile() &
       result(log_write_profile) &
       bind(C, name="rocsolver_log_write_profile")
       import :: rocblas_status_success
       integer(kind(rocblas_status_success)) :: log_write_profile
    end function rocsolver_log_write_profile

    !---------------------------------------------
    ! rocsolver_log_flush_profile
    !---------------------------------------------
    !>  \brief The LOG_FLUSH_PROFILE function prints the profile logging results and clears the
    !>     profile record.
    function rocsolver_log_flush_profile() &
       result(log_flush_profile) &
       bind(C, name="rocsolver_log_flush_profile")
       import :: rocblas_status_success
       integer(kind(rocblas_status_success)) :: log_flush_profile
    end function rocsolver_log_flush_profile

  end interface

  !>  \brief The GET_VERSION_STRING function queries the library version.
  !>
  !>     \details
  !>     @param[out] buf - A buffer that the version string will be written into.
  !>     @param[in] len - The size of the given buffer in bytes.
  interface rocsolver_get_version_string
    function rocsolver_get_version_string_(buf,len) bind(c, name="rocsolver_get_version_string")
      use iso_c_binding
      import
      implicit none
      integer(kind(rocblas_status_success)) :: rocsolver_get_version_string_
      type(c_ptr),value :: buf
      integer(c_size_t),value :: len
    end function

#ifdef USE_FPOINTER_INTERFACES
    module procedure rocsolver_get_version_string_cstr
#endif
  end interface

  !>  \brief The GET_VERSION_STRING_SIZE function queries the minimum buffer size for a
  !>     successful call to `rocsolver_get_version_string`.
  !>
  !>     \details
  !>     @param[out] len - pointer to size_t.
  !>                 The minimum length of buffer to pass to
  !>                 `rocsolver_get_version_string`.
  interface rocsolver_get_version_string_size
    function rocsolver_get_version_string_size_(len) &
        bind(c, name="rocsolver_get_version_string_size")
      use iso_c_binding
      import
      implicit none
