      import
      implicit none
      integer(kind(rocblas_status_success)) :: rocsolver_get_version_string_size_dptr
      type(c_ptr),value :: len
    end function
  end interface

  !>  \brief The SET_ALG_MODE function sets the algorithm mode to be used by the specified function.
  !>
  !>     @param[in] handle - rocblas_handle.
  !>     @param[in] func - `rocsolver_function`.
  !>                 The function that will use the selected algorithm mode.
  !>     @param[in] mode - `rocsolver_alg_mode`.
  !>                 The algorithm mode that will be used by the specified function.
  !>                 rocsolver_alg_mode_mixed is not supported.
  interface rocsolver_set_alg_mode
    function rocsolver_set_alg_mode_(handle,func,mode) bind(c, name="rocsolver_set_alg_mode")
      use iso_c_binding
      import
      implicit none
      integer(kind(rocblas_status_success)) :: rocsolver_set_alg_mode_
      type(c_ptr),value :: handle
      integer(kind(rocsolver_function_bdsqr)),value :: func
      integer(kind(rocsolver_alg_mode_gpu)),value :: mode
    end function

#ifdef USE_FPOINTER_INTERFACES
    module procedure rocsolver_set_alg_mode_typed
#endif
  end interface

  !>  \brief The GET_ALG_MODE function gets the algorithm mode being used by the specified function.
  !>
  !>     @param[in] handle - rocblas_handle.
  !>     @param[in] func - `rocsolver_function`.
  !>                 The specified function.
  !>     @param[out] mode - pointer to `rocsolver_alg_mode`.
  !>                 On exit, the value is overwritten by the algorithm mode used
  !>                 by the specified function.
  interface rocsolver_get_alg_mode
    function rocsolver_get_alg_mode_(handle,func,mode) bind(c, name="rocsolver_get_alg_mode")
      use iso_c_binding
      import
      implicit none
      integer(kind(rocblas_status_success)) :: rocsolver_get_alg_mode_
      type(c_ptr),value :: handle
      integer(kind(rocsolver_function_bdsqr)),value :: func
      type(c_ptr),value :: mode
    end function

#ifdef USE_FPOINTER_INTERFACES
#ifdef USE_ASSUMED_RANK_INTERFACES
    module procedure &
      rocsolver_get_alg_mode_assumed_rank,&
      rocsolver_get_alg_mode_typed
#else
    module procedure &
      rocsolver_get_alg_mode_rank_0,&
      rocsolver_get_alg_mode_rank_1,&
      rocsolver_get_alg_mode_typed
#endif
#endif
  end interface

  !>     \brief The LACGV functions conjugate the complex vector ``x``.
  !>
  !>     \details
  !>     Conjugates the ``n`` entries of a complex vector ``x`` with increment ``incx``.
  !>
  !>     @param[in] handle - rocblas_handle.
  !>     @param[in] n - rocblas_int. n >= 0.
  !>                 The dimension of vector x.
  !>     @param[inout] x - pointer to type. Array on the GPU of size at least n (size depends on the
  !>     value of incx).
  !>                 On entry, the vector x.
  !>                 On exit, each entry is overwritten with its conjugate value.
  !>     @param[in] incx - rocblas_int. incx != 0.
  !>                 The distance between two consecutive elements of x.
  !>                 If incx is negative, the elements of x are indexed in
  !>                 reverse order.
  interface rocsolver_clacgv
    function rocsolver_clacgv_(handle,n,x,incx) bind(c, name="rocsolver_clacgv")
      use iso_c_binding
      import
      implicit none
      integer(kind(rocblas_status_success)) :: rocsolver_clacgv_
      type(c_ptr),value :: handle
      integer(c_int),value :: n
      type(c_ptr),value :: x
      integer(c_int),value :: incx
    end function

#ifdef USE_FPOINTER_INTERFACES
#ifdef USE_ASSUMED_RANK_INTERFACES
    module procedure &
      rocsolver_clacgv_assumed_rank,&
      rocsolver_clacgv_typed
#else
    module procedure &
      rocsolver_clacgv_rank_0,&
      rocsolver_clacgv_rank_1,&
      rocsolver_clacgv_typed
#endif
#endif
  end interface

