      integer(c_int),value :: iu
      real(c_float),value :: abstol
      type(c_ptr),value :: D
      type(c_ptr),value :: E
      type(c_ptr),value :: nev
      type(c_ptr),value :: nsplit
      type(c_ptr),value :: W
      type(c_ptr),value :: iblock
