  interface rocsolver_dgebd2_batched
    function rocsolver_dgebd2_batched_(handle,m,n,A,lda,D,strideD,E,strideE,tauq,strideQ,taup, &
        strideP,batch_count) &
        bind(c, name="rocsolver_dgebd2_batched")
      use iso_c_binding
      import
